const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const defaults=[{id:'cafe',name:'Vianzo Café',icon:'v.',color:'#8c9877',tint:'#f0f3ea'},{id:'burger',name:'Capitão UAU',icon:'U!',color:'#cc956c',tint:'#fbf0e7'},{id:'pizza',name:'Pizzaria',icon:'p.',color:'#78978b',tint:'#edf4f0'},{id:'general',name:'Links gerais',icon:'↗',color:'#a08abc',tint:'#f2edf8'}];
function safe(u){try{return ['http:','https:'].includes(new URL(u).protocol)}catch{return false}}
let data;try{data=JSON.parse(localStorage.getItem('estudio-links-v2'))}catch{}if(!data||!Array.isArray(data.links)||!Array.isArray(data.groups)){data={groups:defaults,links:[]};let old;try{old=JSON.parse(localStorage.getItem('estudio-v1'))}catch{}if(old){Object.entries(old.drives||{}).forEach(([group,url])=>{if(safe(url))data.links.push({id:crypto.randomUUID(),group,title:'Drive de conteúdos',url})});(old.items||[]).forEach(i=>{if(i.url&&safe(i.url))data.links.push({id:crypto.randomUUID(),group:defaults.some(g=>g.id===i.brand)?i.brand:'general',title:i.title,url:i.url})})}}
let active='all',query='';function notify(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(window.timer);window.timer=setTimeout(()=>$('#toast').classList.remove('show'),2700)}
const slots={cafe:['Drive de conteúdos','Templates de frases','Posts prontos'],burger:['Drive de conteúdos','Templates de frases','Posts prontos'],pizza:['Drive de conteúdos','Templates de frases','Posts prontos'],general:['Ideias e referências','Templates para usar']};
function render(){ $('#tabs').innerHTML=[{id:'all',name:'Todos'},...data.groups].map(g=>`<button class="tab ${active===g.id?'active':''}" onclick="filter('${g.id}')">${esc(g.name)}</button>`).join('');let groups=data.groups.filter(g=>active==='all'||active===g.id),html='';groups.forEach(g=>{let list=data.links.filter(l=>l.group===g.id&&`${l.title} ${l.url} ${g.name}`.toLowerCase().includes(query));if(query&&!list.length)return;html+=`<section class="group" style="--color:${g.color};--tint:${g.tint}"><div class="group-head"><div class="brand-icon">${g.icon}</div><div><h2>${esc(g.name)}</h2><small>${list.length?list.length+' '+(list.length===1?'link salvo':'links salvos'):'Adicione os links que você usa'}</small></div><button class="rename" aria-label="Renomear ${esc(g.name)}" title="Renomear" onclick="renameGroup('${g.id}')">✎</button></div><div class="links">${list.map(l=>`<div class="link-row"><span class="link-symbol">↗</span><div class="link-info"><b>${esc(l.title)}</b><small>${esc(domain(l.url))}</small></div><a class="open" href="${esc(safe(l.url)?l.url:'#')}" target="_blank" rel="noopener noreferrer" aria-label="Abrir ${esc(l.title)}">Abrir ↗</a><button class="link-edit" aria-label="Editar ${esc(l.title)}" onclick="editLink('${g.id}','${l.id}')">⋮</button></div>`).join('')}${!list.length&&!query?slots[g.id].map(title=>`<div class="link-row"><span class="link-symbol">↗</span><div class="link-info"><b>${title}</b><small>Nenhum link adicionado</small></div><button class="add-url" onclick="editLink('${g.id}',null,'${title}')">Adicionar ＋</button></div>`).join(''):''}</div><button class="group-add" onclick="editLink('${g.id}')">＋ Adicionar outro link</button></section>`});$('#groups').innerHTML=html||'<div class="no-results">Nenhum link encontrado. Tente outro nome.</div>'}
function domain(url){try{return new URL(url).hostname.replace(/^www\./,'')}catch{return url}}function filter(id){active=id;render()}$('#search').addEventListener('input',e=>{query=e.target.value.trim().toLowerCase();render()});function closeModal(){$('#modal').close()}function modal(title,body){$('#modalbody').innerHTML=`<div class="modal-head"><h2>${esc(title)}</h2><button class="close" onclick="closeModal()" aria-label="Fechar">×</button></div>${body}`;if(!$('#modal').open)$('#modal').showModal()}
function editLink(group=active==='all'?'cafe':active,id=null,title=''){let item=data.links.find(l=>l.id===id);modal(item?'Editar link':'Adicionar link',`<form id="form"><label for="name">Nome para encontrar depois</label><input id="name" name="title" required maxlength="100" placeholder="Ex.: vídeos prontos para Reels" value="${esc(item?.title||title)}"><label for="url">Cole o link aqui</label><input id="url" name="url" type="url" required placeholder="https://drive.google.com/..." value="${esc(item?.url||'')}"><label for="group">Guardar em</label><select id="group" name="group">${data.groups.map(g=>`<option value="${g.id}" ${(item?.group||group)===g.id?'selected':''}>${esc(g.name)}</option>`).join('')}</select><div class="actions">${item?`<button type="button" class="delete" onclick="removeLink('${id}')">Excluir link</button>`:''}<button type="button" class="secondary" onclick="closeModal()">Cancelar</button><button class="primary" type="submit">Salvar link</button></div></form>`);$('#form').onsubmit=async e=>{e.preventDefault();let f=new FormData(e.target),title=f.get('title').trim(),url=f.get('url').trim();if(!title)return notify('Dê um nome para o link.');if(!safe(url))return notify('Use um link começando com https:// ou http://.');const link={id:item?.id||crypto.randomUUID(),title,url,group:f.get('group')};const next={...data,links:item?data.links.map(l=>l.id===id?link:l):[...data.links,link]};if(await save(next)){closeModal();render();notify('Link salvo!')}};if(title)$('#url').focus()}
function renameGroup(id){let g=data.groups.find(g=>g.id===id);modal('Nome da empresa',`<form id="renameform"><label for="groupname">Como você quer chamar este espaço?</label><input id="groupname" name="name" maxlength="40" required value="${esc(g.name)}"><div class="actions"><button class="secondary" type="button" onclick="closeModal()">Cancelar</button><button class="primary">Salvar nome</button></div></form>`);$('#renameform').onsubmit=async e=>{e.preventDefault();let name=new FormData(e.target).get('name').trim();if(name&&await save({...data,groups:data.groups.map(g=>g.id===id?{...g,name}:g)})){closeModal();render();notify('Nome atualizado.')}}}
function removeLink(id){let l=data.links.find(l=>l.id===id);modal('Excluir este link?',`<p>${esc(l.title)} será removido dos seus links salvos.</p><div class="actions"><button class="secondary" onclick="closeModal()">Cancelar</button><button class="primary" onclick="confirmRemove('${id}')">Excluir</button></div>`)}async function confirmRemove(id){if(await save({...data,links:data.links.filter(l=>l.id!==id)})){closeModal();render();notify('Link excluído.')}}
function backup(){if(!data.links.length)return notify('Adicione seu primeiro link para exportar.');let body=data.groups.map(g=>g.name+'\n'+data.links.filter(l=>l.group===g.id).map(l=>l.title+'\n'+l.url).join('\n\n')).join('\n\n──────────\n\n');let url=URL.createObjectURL(new Blob([body],{type:'text/plain;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='meus-links.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('Links exportados.')}

const localArchive=structuredClone(data);
data={groups:structuredClone(defaults),links:[]};
const db=window.supabase.createClient('https://lrfnugrmjdwkbeleqsxi.supabase.co','sb_publishable_2zStg44QLv3rdmv7vpFBOg_MTwtSeZV',{auth:{persistSession:false,autoRefreshToken:false,detectSessionInUrl:false}});
let accessKey='',busy=false,loading=false;
function keyFromURL(value){try{const u=new URL(value,location.origin);return u.searchParams.get('acesso')||new URLSearchParams(u.hash.slice(1)).get('acesso')||''}catch{return ''}}
accessKey=keyFromURL(location.href);
if(!accessKey){try{accessKey=localStorage.getItem('estudio-shared-access')||''}catch{}}
function syncLabel(t){$('#syncstatus').textContent=t}
function message(e){if(e?.code==='42501')return 'Este link de acesso é inválido. Abra pelo link compartilhado com você.';if(e?.code==='23505')return 'Este endereço já está salvo nessa empresa.';if(e?.code==='23514')return 'Confira o nome e o endereço do link.';return 'Não foi possível conectar. Confira a internet e tente novamente.'}
async function request(action='read',payload={}){let r=await db.rpc('organizer_shared',{p_key:accessKey,p_action:action,p_data:payload});if(r.error)throw r.error;return r.data}
function accept(snapshot){data={groups:defaults.map(g=>({...g,name:snapshot.groups.find(x=>x.id===g.id)?.name||g.name})),links:snapshot.links};render();showImportNotice()}
function showAccess(note='Abra pelo link exclusivo que foi compartilhado com você.'){ $('main').hidden=true;$('#authpanel').hidden=false;$('#authpanel').innerHTML=`<div class="auth-card"><span class="eyebrow">SEU ESPAÇO COMPARTILHADO</span><h1>Seus links, juntos.</h1><p>${esc(note)}</p><form id="accessform"><label for="sharedurl">Cole aqui o link completo recebido</label><input id="sharedurl" name="url" type="url" required placeholder="https://…" autocomplete="off"><button class="primary full">Abrir meu organizador</button></form>${accessKey?'<button class="verify-link" onclick="loadCloud()">Tentar novamente</button>':''}</div>`;$('#account').innerHTML='';$('#accessform').onsubmit=async e=>{e.preventDefault();const key=keyFromURL(new FormData(e.target).get('url'));if(!/^[a-f0-9]{64}$/i.test(key))return notify('Copie o link completo recebido na conversa.');accessKey=key;await loadCloud()}}
async function loadCloud(){if(!accessKey)return showAccess();if(loading||busy)return;loading=true;syncLabel('Atualizando…');try{const snapshot=await request();try{localStorage.setItem('estudio-shared-access',accessKey)}catch{}$('#authpanel').hidden=true;$('main').hidden=false;$('#account').innerHTML='<span class="user-email">Espaço compartilhado</span><button class="secondary" onclick="shareSpace()">Copiar acesso ↗</button>';accept(snapshot);syncLabel('Salvo na nuvem · atualizado agora')}catch(e){if(e?.code==='42501'||$('main').hidden)showAccess(message(e));else notify(message(e));syncLabel('Não foi possível atualizar · tente novamente')}finally{loading=false}}
async function shareSpace(){const url=location.origin+location.pathname+'?acesso='+encodeURIComponent(accessKey);try{await navigator.clipboard.writeText(url);notify('Link copiado. Envie apenas para quem vai usar com você.')}catch{modal('Link do espaço',`<p>Quem receber este link pode ver e editar os conteúdos.</p><input style="width:100%;padding:12px;margin-top:15px" readonly value="${esc(url)}" onclick="this.select()">`)}}
async function save(next){if(busy||loading){notify('Aguarde a atualização terminar.');return false}busy=true;syncLabel('Salvando…');let result;try{for(const g of next.groups){if(data.groups.find(x=>x.id===g.id)?.name!==g.name)result=await request('group',{id:g.id,name:g.name})}for(const l of next.links){let old=data.links.find(x=>x.id===l.id);if(!old||old.title!==l.title||old.url!==l.url||old.group!==l.group)result=await request('link',l)}for(const l of data.links){if(!next.links.some(x=>x.id===l.id))result=await request('delete',{id:l.id})}if(result)accept(result);syncLabel('Salvo na nuvem');return true}catch(e){syncLabel('Alteração não salva');notify(message(e));return false}finally{busy=false}}
function pendingImports(){const seen=new Set();return (localArchive.links||[]).filter(l=>{const key=l.group+'|'+l.url;if(seen.has(key))return false;seen.add(key);return safe(l.url)&&l.title&&defaults.some(g=>g.id===l.group)&&!data.links.some(x=>x.url===l.url&&x.group===l.group)})}
function showImportNotice(){let list=pendingImports();$('#cloudnotice').innerHTML=list.length?`<div class="import-notice"><div><b>Você tem ${list.length} link${list.length>1?'s':''} neste navegador.</b><p>Importe para o espaço que vocês dois compartilham.</p></div><button class="secondary" onclick="importLocal()">Importar links</button></div>`:''}
function importLocal(){let list=pendingImports();if(!list.length||busy)return;modal('Importar seus links?',`<p>Os ${list.length} links deste navegador serão adicionados ao espaço compartilhado de vocês. Os links que já estão na nuvem serão mantidos.</p><div class="actions"><button class="secondary" onclick="closeModal()">Cancelar</button><button class="primary" onclick="confirmImport()">Importar</button></div>`)}
async function confirmImport(){if(busy)return;busy=true;syncLabel('Importando…');try{let list=pendingImports();for(let start=0;start<list.length;start+=500){const snapshot=await request('import',{links:list.slice(start,start+500).map(l=>({group:l.group,title:l.title.slice(0,100),url:l.url}))});accept(snapshot)}closeModal();syncLabel('Salvo na nuvem');notify('Links importados.')}catch(e){syncLabel('Importação incompleta · tente novamente');notify(message(e))}finally{busy=false}}
window.addEventListener('hashchange',()=>{const key=keyFromURL(location.href);if(key){accessKey=key;loadCloud()}});
window.addEventListener('focus',()=>{if(accessKey&&!$('#modal').open)loadCloud()});
loadCloud();
